public class PaymentTerms {

    private static final Pattern NET_PATTERN =
        Pattern.compile('(?i)^NET\\s*(\\d{1,3})$');
    private static final Pattern RECEIPT_PATTERN =
        Pattern.compile('(?i)^DUE\\s+ON\\s+RECEIPT$');

    public static Integer parseNetDays(String terms) {
        if (terms != null) {
            String trimmed = terms.trim();
            if (!String.isBlank(trimmed)) {
                Matcher netMatcher = NET_PATTERN.matcher(trimmed);
                if (netMatcher.matches()) {
                    Integer days = Integer.valueOf(netMatcher.group(1));
                    if (days > 180) {
                        throw new TermsOutOfRangeException(
                            'Net days out of range: ' + days);
                    }
                    return days;
                }
                Matcher receiptMatcher = RECEIPT_PATTERN.matcher(trimmed);
                if (receiptMatcher.matches()) {
                    return 0;
                }
            }
        }
        throw new UnsupportedTermsException(
            'Unsupported payment terms: ' + terms);
    }

    public static Date dueDate(Date invoiceDate, String terms) {
        Integer days = parseNetDays(terms);
        return invoiceDate.addDays(days);
    }
}
