public with sharing class RecordSearchService {

    public class SearchException extends Exception {}

    public static List<SObject> search(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        // Validate maxRows
        if (maxRows == null || maxRows < 1 || maxRows > 200) {
            throw new SearchException('maxRows must be between 1 and 200.');
        }

        // Validate object name
        if (String.isBlank(objectApiName)) {
            throw new SearchException('Object API name is required.');
        }

        SObjectType sObjType = Schema.getGlobalDescribe().get(objectApiName.toLowerCase());
        if (sObjType == null) {
            throw new SearchException('Unknown object: ' + objectApiName);
        }

        DescribeSObjectResult objDescribe = sObjType.getDescribe();
        if (!objDescribe.isAccessible()) {
            throw new SearchException('You do not have access to object: ' + objectApiName);
        }

        String canonicalObject = objDescribe.getName();
        Map<String, Schema.SObjectField> fieldMap = objDescribe.fields.getMap();

        // Validate fields list
        if (fields == null || fields.isEmpty()) {
            throw new SearchException('At least one field must be requested.');
        }

        List<String> selectFields = new List<String>();
        selectFields.add('Id');

        for (String f : fields) {
            if (String.isBlank(f)) {
                throw new SearchException('Blank field name is not allowed.');
            }
            Schema.SObjectField token = fieldMap.get(f.toLowerCase());
            if (token == null) {
                throw new SearchException('Unknown field: ' + f);
            }
            DescribeFieldResult dfr = token.getDescribe();
            if (!dfr.isAccessible()) {
                throw new SearchException('You do not have access to field: ' + f);
            }
            String canonical = dfr.getName();
            if (canonical != 'Id') {
                selectFields.add(canonical);
            }
        }

        // Build WHERE clause with bind variables
        List<String> whereClauses = new List<String>();
        Map<String, Object> bindMap = new Map<String, Object>();

        if (filters != null && !filters.isEmpty()) {
            Integer idx = 0;
            for (String key : filters.keySet()) {
                if (String.isBlank(key)) {
                    throw new SearchException('Blank filter field name is not allowed.');
                }
                Schema.SObjectField token = fieldMap.get(key.toLowerCase());
                if (token == null) {
                    throw new SearchException('Unknown filter field: ' + key);
                }
                DescribeFieldResult dfr = token.getDescribe();
                if (!dfr.isAccessible()) {
                    throw new SearchException('You do not have access to filter field: ' + key);
                }
                if (!dfr.isFilterable()) {
                    throw new SearchException('Field cannot be filtered: ' + key);
                }
                String bindName = 'b' + idx;
                whereClauses.add(dfr.getName() + ' = :' + bindName);
                bindMap.put(bindName, filters.get(key));
                idx++;
            }
        }

        // Validate ORDER BY
        String orderByClause = '';
        if (String.isNotBlank(orderByField)) {
            Schema.SObjectField token = fieldMap.get(orderByField.toLowerCase());
            if (token == null) {
                throw new SearchException('Unknown order-by field: ' + orderByField);
            }
            DescribeFieldResult dfr = token.getDescribe();
            if (!dfr.isAccessible()) {
                throw new SearchException('You do not have access to order-by field: ' + orderByField);
            }
            if (!dfr.isSortable()) {
                throw new SearchException('Field cannot be sorted: ' + orderByField);
            }
            orderByClause = ' ORDER BY ' + dfr.getName() + ' ASC';
        }

        // Assemble query
        String soql = 'SELECT ' + String.join(selectFields, ', ')
            + ' FROM ' + canonicalObject;

        if (!whereClauses.isEmpty()) {
            soql += ' WHERE ' + String.join(whereClauses, ' AND ');
        }

        soql += orderByClause;
        bindMap.put('maxRows', maxRows);
        soql += ' LIMIT :maxRows';

        try {
            return Database.queryWithBinds(soql, bindMap, AccessLevel.USER_MODE);
        } catch (Exception e) {
            throw new SearchException(e.getMessage());
        }
    }
}
