public with sharing class ContactLookupAction {

    public class Request {
        @InvocableVariable(label='Email' required=true)
        public String email;
    }

    public class Result {
        @InvocableVariable(label='Contact Id')
        public Id contactId;

        @InvocableVariable(label='Found')
        public Boolean found;
    }

    @InvocableMethod(label='Find Contact by Email')
    public static List<Result> find(List<Request> requests) {
        List<Result> results = new List<Result>();

        // Build set of normalized (trimmed, lowercased) emails to query.
        Set<String> normalizedEmails = new Set<String>();
        for (Request req : requests) {
            String email = normalize(req == null ? null : req.email);
            if (email != null) {
                normalizedEmails.add(email);
            }
        }

        // Map of normalized email -> earliest created Contact Id.
        Map<String, Id> emailToContactId = new Map<String, Id>();
        if (!normalizedEmails.isEmpty()) {
            for (Contact c : [
                SELECT Id, Email
                FROM Contact
                WHERE Email IN :normalizedEmails
                ORDER BY CreatedDate ASC
            ]) {
                if (c.Email == null) {
                    continue;
                }
                String key = normalize(c.Email);
                if (key != null && !emailToContactId.containsKey(key)) {
                    emailToContactId.put(key, c.Id);
                }
            }
        }

        for (Request req : requests) {
            Result res = new Result();
            res.found = false;
            res.contactId = null;

            String email = normalize(req == null ? null : req.email);
            if (email != null && emailToContactId.containsKey(email)) {
                res.contactId = emailToContactId.get(email);
                res.found = true;
            }
            results.add(res);
        }

        return results;
    }

    private static String normalize(String value) {
        if (value == null) {
            return null;
        }
        String trimmed = value.trim();
        if (String.isBlank(trimmed)) {
            return null;
        }
        return trimmed.toLowerCase();
    }
}
