public with sharing class OrderPayloadParser {

    public class PayloadException extends Exception {}

    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines;
        public Decimal total;
    }

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    public static Order parse(String body) {
        if (body == null || String.isBlank(body)) {
            throw new PayloadException('Body is null or blank');
        }

        Object parsed;
        try {
            parsed = JSON.deserializeUntyped(body);
        } catch (Exception e) {
            throw new PayloadException('Invalid JSON: ' + e.getMessage());
        }

        if (!(parsed instanceof Map<String, Object>)) {
            throw new PayloadException('Payload is not a JSON object');
        }
        Map<String, Object> root = (Map<String, Object>) parsed;

        Order order = new Order();

        Object numberObj = root.get('number');
        String number = (numberObj == null) ? null : String.valueOf(numberObj);
        if (number == null || String.isBlank(number)) {
            throw new PayloadException('Missing or blank number');
        }
        order.orderNumber = number;

        Object dateObj = root.get('date');
        if (dateObj != null) {
            try {
                order.orderDate = Date.valueOf(String.valueOf(dateObj));
            } catch (Exception e) {
                throw new PayloadException('Invalid date: ' + e.getMessage());
            }
        }

        Object currencyObj = root.get('currency');
        order.currencyCode = (currencyObj == null) ? null : String.valueOf(currencyObj);

        Object customerObj = root.get('customer');
        if (customerObj != null) {
            if (!(customerObj instanceof Map<String, Object>)) {
                throw new PayloadException('customer is not a JSON object');
            }
            Map<String, Object> customer = (Map<String, Object>) customerObj;
            Object emailObj = customer.get('email');
            order.customerEmail = (emailObj == null) ? null : String.valueOf(emailObj);
        }

        List<Line> lines = new List<Line>();
        Object linesObj = root.get('lines');
        if (linesObj != null) {
            if (!(linesObj instanceof List<Object>)) {
                throw new PayloadException('lines is not a JSON array');
            }
            for (Object lineObj : (List<Object>) linesObj) {
                if (!(lineObj instanceof Map<String, Object>)) {
                    throw new PayloadException('line is not a JSON object');
                }
                lines.add(parseLine((Map<String, Object>) lineObj));
            }
        }
        order.lines = lines;

        Decimal total = 0;
        for (Line l : lines) {
            total += l.lineTotal;
        }
        order.total = total.setScale(2, System.RoundingMode.HALF_UP);

        return order;
    }

    private static Line parseLine(Map<String, Object> lineMap) {
        Line line = new Line();

        Object skuObj = lineMap.get('sku');
        String sku = (skuObj == null) ? null : String.valueOf(skuObj);
        if (sku == null || String.isBlank(sku)) {
            throw new PayloadException('Missing sku');
        }
        line.sku = sku;

        Object qtyObj = lineMap.get('quantity');
        if (qtyObj == null) {
            throw new PayloadException('Missing quantity');
        }
        Integer quantity;
        try {
            quantity = Integer.valueOf(String.valueOf(qtyObj));
        } catch (Exception e) {
            throw new PayloadException('Invalid quantity: ' + e.getMessage());
        }
        if (quantity <= 0) {
            throw new PayloadException('Non-positive quantity');
        }
        line.quantity = quantity;

        Object priceObj = lineMap.get('unitPrice');
        if (priceObj == null) {
            throw new PayloadException('Missing unitPrice');
        }
        Decimal unitPrice = toDecimal(priceObj, 'unitPrice');
        if (unitPrice < 0) {
            throw new PayloadException('Negative unitPrice');
        }
        line.unitPrice = unitPrice;

        Object discountObj = lineMap.get('discount');
        Decimal discount = (discountObj == null) ? 0 : toDecimal(discountObj, 'discount');
        line.discount = discount;

        Decimal raw = (Decimal) quantity * unitPrice * (1 - discount);
        line.lineTotal = raw.setScale(2, System.RoundingMode.HALF_UP);

        return line;
    }

    private static Decimal toDecimal(Object value, String field) {
        try {
            return Decimal.valueOf(String.valueOf(value));
        } catch (Exception e) {
            throw new PayloadException('Invalid ' + field + ': ' + e.getMessage());
        }
    }

    public static String toAcknowledgement(Order order) {
        Map<String, Object> ack = new Map<String, Object>();
        ack.put('number', order.orderNumber);
        ack.put('status', 'RECEIVED');
        ack.put('lineCount', (order.lines == null) ? 0 : order.lines.size());
        ack.put('total', order.total);
        return JSON.serialize(ack);
    }
}
