public with sharing class PicklistService {

    public class PicklistServiceException extends Exception {}

    public class Option {
        public String value;
        public String label;
        public Boolean isDefault;

        public Option(String value, String label, Boolean isDefault) {
            this.value = value;
            this.label = label;
            this.isDefault = isDefault;
        }
    }

    public static List<Option> activeOptions(String objectApiName, String fieldApiName) {
        if (String.isBlank(objectApiName)) {
            throw new PicklistServiceException('Object API name must not be null or blank.');
        }
        if (String.isBlank(fieldApiName)) {
            throw new PicklistServiceException('Field API name must not be null or blank.');
        }

        Schema.SObjectType sobjType = Schema.getGlobalDescribe().get(objectApiName.toLowerCase());
        if (sobjType == null) {
            throw new PicklistServiceException('Object does not exist: ' + objectApiName);
        }

        Map<String, Schema.SObjectField> fieldMap = sobjType.getDescribe().fields.getMap();
        Schema.SObjectField field = fieldMap.get(fieldApiName.toLowerCase());
        if (field == null) {
            throw new PicklistServiceException(
                'Field does not exist on ' + objectApiName + ': ' + fieldApiName);
        }

        Schema.DescribeFieldResult dfr = field.getDescribe();
        Schema.DisplayType dt = dfr.getType();
        if (dt != Schema.DisplayType.PICKLIST && dt != Schema.DisplayType.MULTIPICKLIST) {
            throw new PicklistServiceException(
                'Field is not a picklist or multi-select picklist: ' + fieldApiName);
        }

        List<Option> results = new List<Option>();
        for (Schema.PicklistEntry entry : dfr.getPicklistValues()) {
            if (!entry.isActive()) {
                continue;
            }
            results.add(new Option(entry.getValue(), entry.getLabel(), entry.isDefaultValue()));
        }

        return results;
    }
}
