public with sharing class OpportunityPipelineHandler {

    /**
     * Entry point from the Opportunity trigger. Collects every Account whose
     * open-pipeline figures could have been affected by the DML and recalculates
     * them from scratch.
     */
    public static void handle(
        List<Opportunity> records,
        Map<Id, Opportunity> oldMap,
        Map<Id, Opportunity> newMap
    ) {
        Set<Id> accountIds = new Set<Id>();

        if (newMap != null) {
            // insert / update / undelete: look at new state
            for (Opportunity o : newMap.values()) {
                if (o.AccountId != null) {
                    accountIds.add(o.AccountId);
                }
            }
        }

        if (oldMap != null) {
            // update (reparent) / delete: look at old state
            for (Opportunity o : oldMap.values()) {
                if (o.AccountId != null) {
                    accountIds.add(o.AccountId);
                }
            }
        }

        recalculate(accountIds);
    }

    /**
     * Recomputes FB_Open_Pipeline__c and FB_Open_Opportunities__c for the given
     * accounts and updates only those whose values actually changed. Updating
     * only changed accounts keeps the trigger interaction with AccountTrigger
     * from recursing indefinitely.
     */
    public static void recalculate(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        // Current stored values.
        Map<Id, Account> accounts = new Map<Id, Account>([
            SELECT Id, FB_Open_Pipeline__c, FB_Open_Opportunities__c
            FROM Account
            WHERE Id IN :accountIds
        ]);

        if (accounts.isEmpty()) {
            return;
        }

        // Default every account to 0 / 0 so that accounts losing their last
        // open opportunity are reset correctly.
        Map<Id, Decimal> sumByAccount = new Map<Id, Decimal>();
        Map<Id, Integer> countByAccount = new Map<Id, Integer>();
        for (Id accId : accounts.keySet()) {
            sumByAccount.put(accId, 0);
            countByAccount.put(accId, 0);
        }

        for (AggregateResult ar : [
            SELECT AccountId accId, COUNT(Id) cnt, SUM(Amount) amt
            FROM Opportunity
            WHERE AccountId IN :accounts.keySet()
            AND IsClosed = false
            GROUP BY AccountId
        ]) {
            Id accId = (Id) ar.get('accId');
            Integer cnt = (Integer) ar.get('cnt');
            Decimal amt = (Decimal) ar.get('amt');
            sumByAccount.put(accId, amt == null ? 0 : amt);
            countByAccount.put(accId, cnt == null ? 0 : cnt);
        }

        List<Account> toUpdate = new List<Account>();
        for (Account acc : accounts.values()) {
            Decimal newSum = sumByAccount.get(acc.Id);
            Integer newCount = countByAccount.get(acc.Id);

            Decimal currentSum = acc.FB_Open_Pipeline__c;
            Decimal currentCount = acc.FB_Open_Opportunities__c;

            Boolean sumChanged = (currentSum == null) || (currentSum != newSum);
            Boolean countChanged = (currentCount == null) || (currentCount != newCount);

            if (sumChanged || countChanged) {
                acc.FB_Open_Pipeline__c = newSum;
                acc.FB_Open_Opportunities__c = newCount;
                toUpdate.add(acc);
            }
        }

        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }
    }
}
