/**
 * Pushes newly created Accounts to the ERP as customers.
 *
 * Design notes / deviation:
 *  - A synchronous HTTP callout is not allowed from an after-insert trigger,
 *    so the work is done asynchronously via a Queueable (Database.AllowsCallouts).
 *  - Finance asked for ONE request per account so the ERP can trace each one.
 *    A single transaction allows at most 100 callouts, so accounts are chunked
 *    into groups of up to 100 and one Queueable is enqueued per chunk
 *    (max 2 jobs for the 200-account marketplace batch).
 */
public with sharing class ErpCustomerSync {

    private static final Integer CALLOUTS_PER_JOB = 100;

    private final List<Id> accountIds;

    @TestVisible
    private ErpCustomerSync(List<Id> accountIds) {
        this.accountIds = accountIds;
    }

    /**
     * Entry point from the trigger. Chunks the inserted accounts and enqueues
     * a callout job per chunk.
     */
    public static void syncNewAccounts(List<Account> newAccounts) {
        if (newAccounts == null || newAccounts.isEmpty()) {
            return;
        }

        List<Id> chunk = new List<Id>();
        for (Account acc : newAccounts) {
            chunk.add(acc.Id);
            if (chunk.size() == CALLOUTS_PER_JOB) {
                System.enqueueJob(new Job(chunk));
                chunk = new List<Id>();
            }
        }
        if (!chunk.isEmpty()) {
            System.enqueueJob(new Job(chunk));
        }
    }

    /**
     * Queueable that performs one callout per account in its chunk.
     */
    public class Job implements Queueable, Database.AllowsCallouts {

        private final List<Id> accountIds;

        public Job(List<Id> accountIds) {
            this.accountIds = accountIds;
        }

        public void execute(QueueableContext context) {
            List<Account> accounts = [
                SELECT Id, Name, BillingCountry
                FROM Account
                WHERE Id IN :accountIds
            ];

            for (Account acc : accounts) {
                sendCustomer(acc);
            }
        }
    }

    /**
     * Sends a single account to the ERP as a one-element customer array.
     */
    private static void sendCustomer(Account acc) {
        List<Customer> payload = new List<Customer>{ new Customer(acc) };

        HttpRequest req = new HttpRequest();
        req.setEndpoint('callout:ERP/api/customers');
        req.setMethod('POST');
        req.setHeader('Content-Type', 'application/json');
