public with sharing class LineItemDiscountHandler {

    /**
     * For each new line with a null Discount, set it to the product's standard discount.
     * Lines that already have a Discount (including 0) are left untouched.
     *
     * Rules come from PricingRules.standardDiscountFor. To stay bulk-safe (that method
     * queries per call), we look it up once per distinct Product2Id and cache the result.
     */
    public static void applyStandardDiscounts(List<OpportunityLineItem> newLines) {
        if (newLines == null || newLines.isEmpty()) {
            return;
        }

        Map<Id, Decimal> discountByProduct = new Map<Id, Decimal>();

        for (OpportunityLineItem line : newLines) {
            if (line.Discount != null || line.Product2Id == null) {
                continue;
            }
            if (!discountByProduct.containsKey(line.Product2Id)) {
                discountByProduct.put(
                    line.Product2Id,
                    PricingRules.standardDiscountFor(line.Product2Id)
                );
            }
            line.Discount = discountByProduct.get(line.Product2Id);
        }
    }
}
