import { LightningElement } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

const INTERVAL_MS = 60000;

export default class QueueMonitor extends LightningElement {
    waiting;
    longestWaitMinutes;
    error;
    statsLoaded = false;

    _intervalId;
    _inFlight = false;
    _visibilityHandler;

    connectedCallback() {
        this._visibilityHandler = () => this.handleVisibilityChange();
        document.addEventListener('visibilitychange', this._visibilityHandler);

        if (document.visibilityState !== 'hidden') {
            this.start();
        }
    }

    disconnectedCallback() {
        this.stop();
        if (this._visibilityHandler) {
            document.removeEventListener('visibilitychange', this._visibilityHandler);
            this._visibilityHandler = undefined;
        }
    }

    handleVisibilityChange() {
        if (document.visibilityState === 'hidden') {
            this.stop();
        } else {
            // Became visible: load immediately and (re)start polling.
            this.start();
        }
    }

    start() {
        // Ensure only one polling loop at a time.
        this.stop();
        this.loadStats();
        this._intervalId = setInterval(() => this.loadStats(), INTERVAL_MS);
    }

    stop() {
        if (this._intervalId) {
            clearInterval(this._intervalId);
            this._intervalId = undefined;
        }
    }

    loadStats() {
        // Skip if a request is still in flight, or page is hidden.
        if (this._inFlight || document.visibilityState === 'hidden') {
            return;
        }
        this._inFlight = true;
        getQueueStats()
            .then((stats) => {
                this.waiting = stats.waiting;
                this.longestWaitMinutes = stats.longestWaitMinutes;
                this.error = undefined;
                this.statsLoaded = true;
            })
            .catch((error) => {
                this.error = error;
            })
            .finally(() => {
                this._inFlight = false;
            });
    }
}
