        const emailInput = this.getInput('email');
        const domain = (this.email || '').split('@')[1];
        if (domain && BLOCKED_DOMAINS.includes(domain.toLowerCase())) {
            emailInput.setCustomValidity('Use your work email address.');
        } else {
            emailInput.setCustomValidity('');
        }

        let allValid = true;
        this.inputs.forEach((input) => {
            const valid = input.reportValidity();
            if (!valid) {
                allValid = false;
            }
        });

        if (!allValid) {
            return;
        }

        register({ fullName: this.fullName, email: this.email, company: this.company })
            .then(() => {
                this.dispatchEvent(
                    new ShowToastEvent({
                        title: 'Registered',
                        variant: 'success'
                    })
                );
            })
            .catch((error) => {
                this.dispatchEvent(
                    new ShowToastEvent({
                        title: 'Registration failed',
                        message: error.body.message,
                        variant: 'error'
                    })
                );
            });
    }
