import { LightningElement, api } from 'lwc';

const HANDLED_KEYS = ['ArrowDown', 'ArrowUp', 'Home', 'End', 'Enter', ' '];

export default class StatusListbox extends LightningElement {
    @api label;

    _options = [];
    _value = '';
    _activeValue;

    @api
    get options() {
        return this._options;
    }
    set options(val) {
        this._options = Array.isArray(val) ? val : [];
        this.ensureActive();
    }

    @api
    get value() {
        return this._value;
    }
    set value(val) {
        this._value = val || '';
        // Parent changed the selection: move the active option to it.
        this._activeValue = this._value;
        this.ensureActive();
    }

    ensureActive() {
        const opts = this._options;
        if (!opts.length) {
            this._activeValue = undefined;
            return;
        }
        if (this._value && opts.some((o) => o.value === this._value)) {
            this._activeValue = this._value;
        } else if (
            this._activeValue === undefined ||
            !opts.some((o) => o.value === this._activeValue)
        ) {
            this._activeValue = opts[0].value;
        }
    }

    get computedOptions() {
        return this._options.map((o, i) => ({
            value: o.value,
            label: o.label,
            id: `option-${i}`,
            selected: o.value === this._value ? 'true' : 'false'
        }));
    }

    get activeDescendant() {
        const i = this._options.findIndex((o) => o.value === this._activeValue);
        return i >= 0 ? `option-${i}` : undefined;
    }

    handleKeydown(event) {
        const opts = this._options;
        if (!opts.length) {
            return;
        }
        if (!HANDLED_KEYS.includes(event.key)) {
            return;
        }
        event.preventDefault();

        let idx = opts.findIndex((o) => o.value === this._activeValue);
        if (idx < 0) {
            idx = 0;
        }

        switch (event.key) {
            case 'ArrowDown':
                idx = Math.min(idx + 1, opts.length - 1);
                this._activeValue = opts[idx].value;
                break;
            case 'ArrowUp':
                idx = Math.max(idx - 1, 0);
                this._activeValue = opts[idx].value;
                break;
            case 'Home':
                this._activeValue = opts[0].value;
                break;
            case 'End':
                this._activeValue = opts[opts.length - 1].value;
                break;
            case 'Enter':
            case ' ':
                this.selectValue(this._activeValue);
                break;
            default:
                break;
        }
    }

    handleClick(event) {
        const clicked = event.currentTarget.dataset.value;
        const match = this._options.find(
            (o) => String(o.value) === String(clicked)
        );
        if (match) {
            this.selectValue(match.value);
        }
    }

    selectValue(val) {
        this._activeValue = val;
        if (val === this._value) {
            return;
        }
        this._value = val;
        this.dispatchEvent(new CustomEvent('change', { detail: { value: val } }));
    }
}
