import { LightningElement, api } from 'lwc';

export default class TaskChecklist extends LightningElement {
    _heading = '';
    items = [];
    newLabel = '';
    nextId = 1;

    @api
    get heading() {
        return this._heading;
    }
    set heading(value) {
        this._heading = value;
    }

    @api
    get tasks() {
        return this._tasks;
    }
    set tasks(value) {
        this._tasks = value;
        this.items = Array.isArray(value)
            ? value.map((task) => ({ ...task }))
            : [];
    }

    get displayHeading() {
        return this._heading ? this._heading.toUpperCase() : '';
    }

    get remaining() {
        return this.items.filter((task) => !task.done).length;
    }

    handleLabelChange(event) {
        this.newLabel = event.detail.value;
    }

    handleAdd() {
        const label = (this.newLabel || '').trim();
        if (!label) {
            return;
        }
        this.items = [
            ...this.items,
            { id: `new-${this.nextId++}`, label, done: false }
        ];
        this.newLabel = '';
        this.dispatchEvent(new CustomEvent('taskadded', { detail: { label } }));
    }

    handleToggle(event) {
        const id = event.target.dataset.id;
        this.items = this.items.map((task) =>
            task.id === id ? { ...task, done: !task.done } : task
        );
    }
}
