public with sharing class EmployerService {

    /**
     * Sets the current employer (Organization) for each contact.
     *
     * NPSP's Affiliations trigger watches Contact.npsp__Primary_Affiliation__c.
     * When that lookup changes, NPSP automatically:
     *   - creates a new Current, primary npe5__Affiliation__c to the new org, and
     *   - flips the old primary affiliation to Former, non-primary with EndDate = today.
     *
     * So the "standard mechanism" here is simply to update the lookup, letting NPSP
     * do the affiliation bookkeeping. This keeps us to 1 query + 1 DML.
     *
     * @param employerByContactId Map of Contact Id -> Organization Account Id.
     */
    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        List<Contact> toUpdate = new List<Contact>();

        // 1 SOQL query
        for (Contact c : [
            SELECT Id, npsp__Primary_Affiliation__c
            FROM Contact
            WHERE Id IN :employerByContactId.keySet()
        ]) {
            Id newEmployerId = employerByContactId.get(c.Id);
            if (newEmployerId == null) {
                continue;
            }
            // Skip if the org is already the contact's primary affiliation.
            if (c.npsp__Primary_Affiliation__c == newEmployerId) {
                continue;
            }
            c.npsp__Primary_Affiliation__c = newEmployerId;
            toUpdate.add(c);
        }

        if (!toUpdate.isEmpty()) {
            // 1 DML statement; NPSP triggers handle affiliation creation/retirement.
            update toUpdate;
        }
    }
}
