public with sharing class GiftImportService {

    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;        // the donor's personal email
        public Decimal amount;
        public Date giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id contactId;        // the matched or created contact
        public Id opportunityId;    // the created donation
        public String errorMessage; // NPSP's failure information when success is false
    }

    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        List<ImportResult> results = new List<ImportResult>();
        if (gifts == null || gifts.isEmpty()) {
            return results;
        }

        // Stage one NPSP Data Import record per gift, keeping input order.
        List<npsp__DataImport__c> dataImports = new List<npsp__DataImport__c>();
        for (WebGift gift : gifts) {
            dataImports.add(new npsp__DataImport__c(
                npsp__Contact1_Firstname__c      = gift != null ? gift.firstName : null,
                npsp__Contact1_Lastname__c       = gift != null ? gift.lastName  : null,
                npsp__Contact1_Personal_Email__c = gift != null ? gift.email     : null,
                npsp__Donation_Amount__c         = gift != null ? gift.amount    : null,
                npsp__Donation_Date__c           = gift != null ? gift.giftDate   : null,
                npsp__Donation_Donor__c          = 'Contact1'
            ));
        }

        // Persist the staged rows so they remain in the org as the audit trail.
        insert dataImports;

        // Use the org's Data Import settings (defaults: match contacts on
        // first name / last name / email, and never match existing donations).
        npsp__Data_Import_Settings__c diSettings =
            npsp__Data_Import_Settings__c.getOrgDefaults();

        // Process the staged rows synchronously, in this same transaction.
        // isDryRun = false so NPSP performs the actual import.
        npsp.BDI_DataImport_API.processDataImportRecords(diSettings, dataImports, false);

        // Re-query the processed records to read back NPSP's results.
        Set<Id> diIds = new Set<Id>();
        for (npsp__DataImport__c di : dataImports) {
            diIds.add(di.Id);
        }

        Map<Id, npsp__DataImport__c> processedById = new Map<Id, npsp__DataImport__c>(
            [SELECT Id,
                    npsp__Status__c,
                    npsp__Contact1Imported__c,
                    npsp__DonationImported__c,
                    npsp__FailureInformation__c
             FROM npsp__DataImport__c
             WHERE Id IN :diIds]
        );

        // Build one ImportResult per gift, in input order.
        for (npsp__DataImport__c staged : dataImports) {
            npsp__DataImport__c processed = processedById.get(staged.Id);

            ImportResult res = new ImportResult();
            if (processed != null) {
                res.contactId       = processed.npsp__Contact1Imported__c;
                res.opportunityId   = processed.npsp__DonationImported__c;
                res.success         = processed.npsp__Status__c == 'Imported';
                res.errorMessage    = res.success ? null : processed.npsp__FailureInformation__c;
            } else {
                res.success      = false;
                res.errorMessage = 'Data Import record could not be retrieved after processing.';
            }
            results.add(res);
        }

        return results;
    }
}
