public with sharing class SoftCreditService {

    public class SoftCreditException extends Exception {}

    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return;
        }

        Set<Id> oppIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();
        for (SoftCreditRequest r : requests) {
            oppIds.add(r.opportunityId);
            contactIds.add(r.contactId);
        }

        // SOQL 1 - opportunities for validation
        Map<Id, Opportunity> oppMap = new Map<Id, Opportunity>([
            SELECT Id, Amount, npsp__Primary_Contact__c
            FROM Opportunity
            WHERE Id IN :oppIds
        ]);

        // Validate the whole call before any DML
        for (SoftCreditRequest r : requests) {
            Opportunity opp = oppMap.get(r.opportunityId);
            if (opp == null) {
                throw new SoftCreditException('Opportunity not found: ' + r.opportunityId);
            }
            if (r.contactId != null && r.contactId == opp.npsp__Primary_Contact__c) {
                throw new SoftCreditException(
                    'Contact ' + r.contactId + ' is the primary contact of opportunity ' + r.opportunityId + '.');
            }
            if (r.amount == null || r.amount <= 0) {
                throw new SoftCreditException('Soft credit amount must be a positive value.');
            }
            if (opp.Amount == null || r.amount > opp.Amount) {
                throw new SoftCreditException(
                    'Soft credit amount cannot exceed the opportunity amount for ' + r.opportunityId + '.');
            }
        }

        // SOQL 2 - existing contact roles for these pairs
        Map<String, List<OpportunityContactRole>> ocrMap =
            new Map<String, List<OpportunityContactRole>>();
        for (OpportunityContactRole ocr : [
            SELECT Id, OpportunityId, ContactId, Role
            FROM OpportunityContactRole
            WHERE OpportunityId IN :oppIds AND ContactId IN :contactIds
        ]) {
            String key = ocr.OpportunityId + '-' + ocr.ContactId;
            if (!ocrMap.containsKey(key)) {
                ocrMap.put(key, new List<OpportunityContactRole>());
            }
            ocrMap.get(key).add(ocr);
        }

        List<OpportunityContactRole> ocrUpsert = new List<OpportunityContactRole>();
        List<OpportunityContactRole> ocrDelete = new List<OpportunityContactRole>();
        // Track the single OCR that each request ends up linked to
        Map<Integer, OpportunityContactRole> reqOcr = new Map<Integer, OpportunityContactRole>();

        for (Integer i = 0; i < requests.size(); i++) {
            SoftCreditRequest r = requests[i];
            String key = r.opportunityId + '-' + r.contactId;
            List<OpportunityContactRole> existing = ocrMap.get(key);

            OpportunityContactRole target;
            if (existing == null || existing.isEmpty()) {
                target = new OpportunityContactRole(
                    OpportunityId = r.opportunityId,
                    ContactId = r.contactId,
                    Role = r.role
                );
            } else {
                // Keep exactly one; update its role and remove any extras
                target = existing[0];
                target.Role = r.role;
                for (Integer j = 1; j < existing.size(); j++) {
                    ocrDelete.add(existing[j]);
                }
            }
            ocrUpsert.add(target);
            reqOcr.put(i, target);
        }

        // DML 1 - create/update the contact roles so we have their Ids
        upsert ocrUpsert;

        // DML 2 - remove duplicate contact roles so exactly one remains
        if (!ocrDelete.isEmpty()) {
            delete ocrDelete;
        }

        // SOQL 3 - existing partial soft credits for these pairs
        Map<String, npsp__Partial_Soft_Credit__c> pscMap =
            new Map<String, npsp__Partial_Soft_Credit__c>();
        for (npsp__Partial_Soft_Credit__c p : [
            SELECT Id, npsp__Opportunity__c, npsp__Contact__c,
                   npsp__Amount__c, npsp__Role_Name__c, npsp__Contact_Role_ID__c
            FROM npsp__Partial_Soft_Credit__c
            WHERE npsp__Opportunity__c IN :oppIds AND npsp__Contact__c IN :contactIds
        ]) {
            pscMap.put(p.npsp__Opportunity__c + '-' + p.npsp__Contact__c, p);
        }

        List<npsp__Partial_Soft_Credit__c> pscUpsert = new List<npsp__Partial_Soft_Credit__c>();
        for (Integer i = 0; i < requests.size(); i++) {
            SoftCreditRequest r = requests[i];
            String key = r.opportunityId + '-' + r.contactId;

            npsp__Partial_Soft_Credit__c psc = pscMap.get(key);
            if (psc == null) {
                psc = new npsp__Partial_Soft_Credit__c(
                    npsp__Opportunity__c = r.opportunityId,
                    npsp__Contact__c = r.contactId
                );
            }
            psc.npsp__Amount__c = r.amount;
            psc.npsp__Role_Name__c = r.role;
            psc.npsp__Contact_Role_ID__c = String.valueOf(reqOcr.get(i).Id);
            pscUpsert.add(psc);
        }

        // DML 3 - create/update the partial soft credits
        upsert pscUpsert;
    }
}
