public with sharing class AccountOwnershipService {
    public static void reassign(Set<Id> accountIds, Id newOwnerId) {
        if (accountIds == null || accountIds.isEmpty() || newOwnerId == null) {
            return;
        }

        // Update the Accounts themselves with Account trigger actions bypassed.
        List<Account> accountsToUpdate = new List<Account>();
        for (Account acct : [SELECT Id FROM Account WHERE Id IN :accountIds]) {
            acct.OwnerId = newOwnerId;
            accountsToUpdate.add(acct);
        }

        // Collect the Contacts belonging to those Accounts (Contact actions run normally).
        List<Contact> contactsToUpdate = new List<Contact>();
        for (Contact con : [SELECT Id FROM Contact WHERE AccountId IN :accountIds]) {
            con.OwnerId = newOwnerId;
            contactsToUpdate.add(con);
        }

        TriggerBase.bypass('Account');
        try {
            update accountsToUpdate;
        } finally {
            // Ensure Account automation behaves normally for the rest of the transaction,
            // whether the DML above succeeded or threw.
            TriggerBase.clearBypass('Account');
        }

        update contactsToUpdate;
    }
}
