public with sharing class TA_Opportunity_LogAmountChange implements TriggerAction.AfterUpdate {
    public void afterUpdate(List<Opportunity> triggerNew, List<Opportunity> triggerOld) {
        Map<Id, Opportunity> oldMap = new Map<Id, Opportunity>(triggerOld);

        List<Task> tasks = new List<Task>();
        for (Opportunity opp : triggerNew) {
            // Only consider each Opportunity the first time it is seen in the
            // after-update context of this transaction. The rounding action
            // (Order 20) issues a second update that re-runs every Opportunity
            // after-update action; on that recursive pass the framework has
            // already seen this record, so we skip it and avoid a duplicate task.
            Integer timesSeen = TriggerBase.idToNumberOfTimesSeenAfterUpdate.get(opp.Id);
            if (timesSeen != 1) {
                continue;
            }

            Opportunity oldOpp = oldMap.get(opp.Id);
            if (opp.Amount != oldOpp.Amount) {
                tasks.add(new Task(
                    Subject = 'Amount changed',
                    WhatId = opp.Id,
                    Status = 'Completed'
                ));
            }
        }

        if (!tasks.isEmpty()) {
            insert tasks;
        }
    }
}
