/**
 * Before insert Contact action: when a new contact has an Account and all four
 * mailing address fields are blank, copy the account's billing address into them.
 */
public inherited sharing class TA_Contact_InheritMailingAddress implements TriggerAction.BeforeInsert {
    public void beforeInsert(List<SObject> triggerNew) {
        Map<Id, Account> accountsById = TA_Contact_Queries.getInstance().accountsById;

        for (SObject record : triggerNew) {
            Contact con = (Contact) record;
            if (con.AccountId == null) {
                continue;
            }

            Boolean mailingBlank =
                String.isBlank(con.MailingStreet) &&
                String.isBlank(con.MailingCity) &&
                String.isBlank(con.MailingPostalCode) &&
                String.isBlank(con.MailingCountry);
            if (!mailingBlank) {
                continue;
            }

            Account acc = accountsById.get(con.AccountId);
            if (acc == null) {
                continue;
            }

            con.MailingStreet = acc.BillingStreet;
            con.MailingCity = acc.BillingCity;
            con.MailingPostalCode = acc.BillingPostalCode;
            con.MailingCountry = acc.BillingCountry;
        }
    }
}
